import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.listing.*;
import java.nio.file.*;
import java.io.*;
import java.util.*;
public class N3DRecoverCandidates extends GhidraScript {
 public void run() throws Exception {
  LinkedHashSet<String> candidates=new LinkedHashSet<>(Files.readAllLines(Paths.get(getScriptArgs()[0])));
  candidates.addAll(Arrays.asList("1000:03e8","1000:03f4","1000:092c","1000:13aa"));
  try(PrintWriter p=new PrintWriter(getScriptArgs()[1])){
   p.println("entry\tdisassembled\tfunction\tstatus");
   for(String s:candidates){Address a=toAddr(s);if(currentProgram.getFunctionManager().getFunctionContaining(a)!=null){p.println(s+"\tfalse\t\talready_owned");continue;}
    boolean dis=disassemble(a);Function f=createFunction(a,"CANDIDATE_"+s.replace(':','_'));p.println(s+"\t"+dis+"\t"+(f==null?"":f.getEntryPoint())+"\theuristic_requires_review");
   }
  }
 }
}

