import ghidra.app.script.GhidraScript;
import ghidra.app.cmd.function.CreateFunctionCmd;
import ghidra.program.model.address.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.pcode.JumpTable;
import ghidra.program.model.symbol.*;
import java.util.*;
public class N3DFixFormatSwitch extends GhidraScript {
 public void run() throws Exception {
  Address branch=toAddr("1008:4e7d");Function f=getFunctionContaining(branch);
  ArrayList<Address> dest=new ArrayList<>();
  for(int i=0;i<8;i++){
   int offset=getShort(toAddr("1008:4e14").add(i*2))&0xffff;
   Address a=toAddr(String.format("1008:%04x",offset));dest.add(a);disassemble(a);
   currentProgram.getListing().getInstructionAt(branch).addOperandReference(0,a,RefType.COMPUTED_JUMP,SourceType.USER_DEFINED);
   println("TABLE "+i+" -> "+a);
  }
  new JumpTable(branch,dest,true,0).writeOverride(f);
  CreateFunctionCmd.fixupFunctionBody(currentProgram,f,monitor);
  println("FIXED_BODY "+f.getBody());
 }
}

