public class N3DDeepExport extends GhidraScript {
 String clean(Object s){return String.valueOf(s).replace("\t"," ").replace("\n"," ").replace("\r"," ");}
 public void run() throws Exception {
  Path out=Paths.get(getScriptArgs()[0]); Files.createDirectories(out.resolve("decompiled"));
  DecompInterface d=new DecompInterface(); d.openProgram(currentProgram);
  int total=0,ok=0;
  try(PrintWriter inv=new PrintWriter(out.resolve("functions.tsv").toFile()); PrintWriter refs=new PrintWriter(out.resolve("references.tsv").toFile()); PrintWriter asm=new PrintWriter(out.resolve("listing.tsv").toFile()); PrintWriter gaps=new PrintWriter(out.resolve("unowned_instructions.tsv").toFile()); PrintWriter blocks=new PrintWriter(out.resolve("blocks.tsv").toFile())) {
   inv.println("entry\tname\tsize\tthunk\texternal\tcallers\tcallees\tdecompiled\terror"); refs.println("from\tto\ttype\towner\ttarget_symbol"); asm.println("address\tbytes\tinstruction\tfunction");gaps.println("address\tinstruction");blocks.println("name\tstart\tend\texecutable\tinitialized");
   for(var b:currentProgram.getMemory().getBlocks())blocks.println(b.getName()+"\t"+b.getStart()+"\t"+b.getEnd()+"\t"+b.isExecute()+"\t"+b.isInitialized());
   FunctionIterator fs=currentProgram.getFunctionManager().getFunctions(true);
   while(fs.hasNext()&&!monitor.isCancelled()) {
    Function f=fs.next(); total++; boolean success=false;String error="";
    if(!f.isExternal()){DecompileResults r=d.decompileFunction(f,30,monitor);success=r.decompileCompleted();error=r.getErrorMessage();if(success){ok++;Files.writeString(out.resolve("decompiled").resolve(f.getEntryPoint().toString().replace(':','_')+".c"),"/* "+f.getEntryPoint()+" "+f.getName()+" */\n"+r.getDecompiledFunction().getC());}}
    inv.println(f.getEntryPoint()+"\t"+clean(f.getName())+"\t"+f.getBody().getNumAddresses()+"\t"+f.isThunk()+"\t"+f.isExternal()+"\t"+f.getCallingFunctions(monitor).size()+"\t"+f.getCalledFunctions(monitor).size()+"\t"+success+"\t"+clean(error));inv.flush();
    if(total%100==0)println("PROGRESS "+total+" decompiled="+ok);
   }
   for(Instruction i:currentProgram.getListing().getInstructions(true)) {
    Function f=currentProgram.getFunctionManager().getFunctionContaining(i.getAddress());String owner=f==null?"":f.getEntryPoint().toString();StringBuilder hex=new StringBuilder();for(byte b:i.getBytes())hex.append(String.format("%02x",b&255));asm.println(i.getAddress()+"\t"+hex+"\t"+clean(i)+"\t"+owner);if(f==null)gaps.println(i.getAddress()+"\t"+clean(i));
    for(Reference r:i.getReferencesFrom()){Symbol s=currentProgram.getSymbolTable().getPrimarySymbol(r.getToAddress());refs.println(r.getFromAddress()+"\t"+r.getToAddress()+"\t"+r.getReferenceType()+"\t"+owner+"\t"+clean(s==null?"":s.getName(true)));}
   }
  } finally {d.dispose();} println("COMPLETE functions="+total+" decompiled="+ok);
 }
}

