import ghidra.app.script.GhidraScript;
import ghidra.program.model.listing.*;
import ghidra.program.model.address.*;
import java.io.*;
public class N3DCoverage extends GhidraScript {
 public void run() throws Exception {
  String dir=getScriptArgs()[0];
  try(PrintWriter p=new PrintWriter(dir+"/coverage.tsv");PrintWriter u=new PrintWriter(dir+"/undefined_ranges.tsv");PrintWriter t=new PrintWriter(dir+"/candidate_details.txt")) {
   p.println("block\tbytes\tinstruction_bytes\tdefined_data_bytes\tundefined_bytes");u.println("start\tend\tlength");
   for(var b:currentProgram.getMemory().getBlocks())if(b.isExecute()&&b.isInitialized()){
    long code=0,data=0,unknown=0;Address start=null,last=null;
    for(Address a=b.getStart();a.compareTo(b.getEnd())<=0;a=a.add(1)){
     boolean und=false;
     if(currentProgram.getListing().getInstructionContaining(a)!=null)code++;
     else {Data d=currentProgram.getListing().getDataContaining(a);if(d!=null&&d.isDefined())data++;else {unknown++;und=true;}}
     if(und){if(start==null)start=a;last=a;}else if(start!=null){u.println(start+"\t"+last+"\t"+(last.subtract(start)+1));start=null;}
    }
    if(start!=null)u.println(start+"\t"+last+"\t"+(last.subtract(start)+1));
    p.println(b.getName()+"\t"+b.getSize()+"\t"+code+"\t"+data+"\t"+unknown);
   }
   for(String s:new String[]{"1000:03e8","1000:0400","1000:0422","1000:0752","1000:092c","1000:13aa","1000:16a6"}){
    Address a=toAddr(s); t.println("TARGET "+s+" containing="+currentProgram.getFunctionManager().getFunctionContaining(a));
    for(var r:currentProgram.getReferenceManager().getReferencesTo(a))t.println("XREF "+r);
    for(CodeUnit cu:currentProgram.getListing().getCodeUnits(new AddressSet(a,a.add(100)),true))t.println(cu.getAddress()+" "+cu);
   }
  }
 }
}
